msg.payload = p;
return msg;

let cap = '실시간 온실 영상 (AI 대기: MQTT 캡션 수신 시 갱신)';
try {
  let o = msg.payload;
  if (typeof o === 'string') {
    try { o = JSON.parse(o); } catch (e2) { /* 그대로 두고 아래에서 무시 */ }
  }
  if (o && typeof o === 'object' && !Array.isArray(o)) {
    if (o.caption && String(o.caption).trim()) cap = String(o.caption).trim();
    else if (typeof o.count === 'number') cap = '검출 ' + o.count + '개 (종류 정보 없음)';
  }
} catch (e) {}
msg.payload = cap;
return msg;

const d = msg.device || 'unknown';
const p = msg.payload || {};
const out = [];
if (p.ph   !== undefined) out.push({ topic: `${d}:pH`,   payload: p.ph });
if (p.ec   !== undefined) out.push({ topic: `${d}:EC`,   payload: p.ec });
if (p.temp !== undefined) out.push({ topic: `${d}:Temp`, payload: p.temp });
return [out];

// PH-W3988 (Tuya dgnbj, proto 3.5) — DP from tuya-local #555/#562 + IoT shadow
// 8 temp°C×10, 102 pH×100, 107 TDS ppm, 110 EC µS/cm, 113 salinity ppm, 116 S.G×1000, 119 ORP mV (optional)
const DEVICE = 'phw3988';
const MAP = {
  temp: { dp: '8', scale: 10 },
  ph:   { dp: '102', scale: 100 },
  tds:  { dp: '107', scale: 1 },
  ec:   { dp: '110', scale: 1 },
  salt: { dp: '113', scale: 100 },
  sg:   { dp: '116', scale: 1000 }
};

let src = null;
const p = msg.payload;
if (p && typeof p === 'object') {
  if (p.dps && typeof p.dps === 'object') src = p.dps;
  else if (p.data && p.data.dps && typeof p.data.dps === 'object') src = p.data.dps;
  else if (Object.keys(p).every(k => /^\d+$/.test(k))) src = p;
}
if (!src || typeof src !== 'object') return null;

const norm = {};
for (const [k, v] of Object.entries(src)) norm[String(k)] = v;
src = norm;

const parsed = { ts: new Date().toISOString() };
for (const [k, cfg] of Object.entries(MAP)) {
  const raw = src[cfg.dp];
  if (raw === undefined || raw === null) continue;
  const v = Number(raw) / cfg.scale;
  if (Number.isFinite(v)) parsed[k] = Math.round(v * 1000) / 1000;
}

const key = 'last_' + DEVICE;
const last = flow.get(key) || {};
const merged = Object.assign({}, last, parsed);
flow.set(key, merged);
msg.payload = merged;
msg.device = DEVICE;
return msg;

const p = msg.payload || {};
// msg.payload가 string(JSON)으로 들어오는 경우도 있으니 보정
let obj = p;
if (typeof obj === 'string') {
  try { obj = JSON.parse(obj); } catch (e) { return null; }
}
if (!obj || typeof obj !== 'object') return null;

// Arduino가 기대하는 키: ph, ec, temp
const out = {
  ph: obj.ph,
  ec: obj.ec,
  temp: obj.temp
};

// 값이 하나도 없으면 publish 안 함
if (out.ph === undefined && out.ec === undefined && out.temp === undefined) return null;

msg.topic = 'cronus/water';
msg.payload = JSON.stringify(out);
return msg;

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const p = msg.payload || {};
const minMs = parseInt((env.get('CRONUSFARM_PHW_SQLITE_MIN_MS') || '30000').toString(), 10) || 30000;
const now = Date.now();
const last = flow.get('lastPhwSensorMs') || 0;
if (now - last < minMs) return null;
flow.set('lastPhwSensorMs', now);
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
msg.method = 'POST';
msg.url = base + '/ingest/sensor';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: 'cronusfarm-01',
  zone: 'phw3988',
  ph: p.ph, ec: p.ec, temp_c: p.temp,
  source: 'phw3988',
  raw_json: JSON.stringify(p),
  ts_ms: now
});
return msg;

const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
msg.method = 'GET';
msg.url = base + '/api/sensor/latest?device_id=cronusfarm-01&zone=phw3988';
msg.headers = {};
delete msg.payload;
return msg;

let j = msg.payload;
if (typeof j === 'string') { try { j = JSON.parse(j); } catch (e) { return null; } }
if (!j || !j.ok) return null;
let raw = j.raw_json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = {}; } }
const p = {
  ph: j.ph != null ? j.ph : raw.ph,
  ec: j.ec != null ? j.ec : raw.ec,
  temp: j.temp_c != null ? j.temp_c : raw.temp,
  tds: raw.tds, salt: raw.salt, sg: raw.sg
};
msg.payload = p;
return msg;

const localDev = ['1', 'true', 'yes'].includes(
  String(env.get('CRONUSFARM_LOCAL_DEV') || '').toLowerCase()
);
if (localDev) {
  return [msg, null];
}
return [null, msg];

const piHost = String(env.get('CRONUSFARM_PI_HOST') || 'ida.mango-larch.ts.net').replace(/\/+$/, '');
const mqttPort = parseInt(String(env.get('CRONUSFARM_MQTT_PORT') || '1883'), 10) || 1883;
const nginxPort = parseInt(String(env.get('CRONUSFARM_NGINX_PORT') || '1880'), 10) || 1880;
const nrPort = parseInt(String(env.get('CRONUSFARM_NR_PORT') || '51882'), 10) || 51882;
const bridgePort = parseInt(String(env.get('CRONUSFARM_SQLITE_BRIDGE_PORT') || '18766'), 10) || 18766;
const http = require('http');
const net = require('net');

function httpOk(port, path) {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: piHost,
      port,
      path: path || '/',
      method: 'GET',
      timeout: 5000
    }, (res) => {
      resolve(res.statusCode >= 200 && res.statusCode < 500);
    });
    req.on('error', () => resolve(false));
    req.setTimeout(5000, () => { req.destroy(); resolve(false); });
    req.end();
  });
}

function tcpOk(port) {
  return new Promise((resolve) => {
    const s = net.connect({ host: piHost, port, timeout: 5000 }, () => { s.end(); resolve(true); });
    s.on('error', () => resolve(false));
    s.setTimeout(5000, () => { s.destroy(); resolve(false); });
  });
}

(async () => {
  const nrOk = (await httpOk(nginxPort, '/')) || (await httpOk(nrPort, '/'));
  const mqOk = await tcpOk(mqttPort);
  const bridgeOk = await httpOk(bridgePort, '/api/channel/status?device_id=cronusfarm-01&channel=pump_a1');
  const ok = nrOk && mqOk;
  node.send([
    { payload: ok ? '원격 Pi (' + piHost + ') 응답 OK' : '원격 Pi 응답 없음' },
    { payload: ok ? 'Tailscale' : '(미연결)' },
    { payload: piHost },
    { payload: piHost },
    { payload: nrOk ? 'active' : 'inactive' },
    { payload: mqOk ? 'active' : 'inactive' }
  ]);
})().catch((e) => {
  node.warn('fn_pi_remote_probe: ' + e);
  node.send([
    { payload: '원격 Pi 프로브 오류' },
    { payload: '(미연결)' },
    { payload: piHost },
    { payload: piHost },
    { payload: 'inactive' },
    { payload: 'inactive' }
  ]);
});
return null;

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

// FlexDash 위젯마다 topic이 다르게 들어올 수 있어 방어적으로 처리
const candidates = [
  msg.topic,
  msg.fd_output_topic,
  msg.fdOutputTopic,
  msg?._fd?.output_topic,
  msg?._fd?.outputTopic,
  msg?.widget?.topic
];
const k = (candidates.find(x => (x ?? '').toString().trim().length > 0) ?? '').toString().trim();
if(!k) return null;

// FlexDash toggle payload는 기본 true/false 또는 1/0
const v = (msg.payload===1 || msg.payload===true || msg.payload==='1' || msg.payload==='on') ? 1 : 0;

const t = `cronusfarm/${devId}/cmd`;
const m1 = {topic:t, payload:`auto_${k}=0`};
const m2 = {topic:t, payload:`${k}=${v}`};
return [m1, m2];
